// 1. ฟังก์ชันติดตั้งและสร้างแผ่นงานทั้งหมดอัตโนมัติ (1-Click Database Provisioning)
function INITIALIZE_SYSTEM_DATABASE() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!ss) {
    Logger.log('❌ ข้อผิดพลาด: ไม่พบ Google Spreadsheet กรุณาเปิด Apps Script จากเมนู ส่วนขยาย > Apps Script ภายในชีตของคุณโดยตรง');
    return 'ERROR: Not container-bound';
  }
  setupSheets(ss);
  Logger.log('✅ สำเร็จ 100%: ติดตั้งฐานข้อมูล Smart Logistics ครบทุกแผ่นงานเรียบร้อยแล้ว!');
  Logger.log('ชื่อไฟล์ชีต: ' + ss.getName() + ' (ID: ' + ss.getId() + ')');
  return 'SUCCESS';
}

function INITIALIZE_SMART_DATABASE() {
  return INITIALIZE_SYSTEM_DATABASE();
}

function testConnection() {
  return INITIALIZE_SYSTEM_DATABASE();
}

function onOpen() {
  try {
    SpreadsheetApp.getUi()
      .createMenu('🚛 ระบบจัดการขนส่งและงานช่าง')
      .addItem('🛠️ ติดตั้ง/รีเซ็ตแผ่นงานฐานข้อมูลทั้งหมด', 'INITIALIZE_SYSTEM_DATABASE')
      .addToUi();
  } catch (e) {}
}

// ฟังก์ชันสร้างหรือดึงแผ่นงาน พร้อมใส่หัวตารางและสีสันอย่างปลอดภัย
function getOrCreateSheet(ss, name, headers, tabColor, headerBg, headerColor) {
  if (!ss) return null;
  var sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
  }
  if (sheet.getLastRow() === 0 && headers && headers.length > 0) {
    sheet.appendRow(headers);
    if (tabColor) {
      try { sheet.setTabColor(tabColor); } catch (e) {}
    }
    if (headerBg) {
      try {
        sheet.getRange(1, 1, 1, headers.length)
          .setFontWeight('bold')
          .setBackground(headerBg)
          .setFontColor(headerColor || '#000000');
        sheet.setFrozenRows(1);
      } catch (e) {}
    }
  }
  return sheet;
}

